+    private static boolean isOnlyLineBreaks(String value) {
+        for (int i = 0; i < value.length(); i++) {
+            char current = value.charAt(i);
+            if (current == '\r' && i + 1 < value.length() && value.charAt(i + 1) == '\n') {
+                i++;
