+    private static boolean isSharedFile(String description, String fileName, Path file, Properties properties, Path folder) {
+        for (String otherDescription : properties.stringPropertyNames()) {
+            if (description.equals(otherDescription)) {
+                continue;
+            }
+            String otherName = properties.getProperty(otherDescription);
+            if (fileName.equals(otherName)) {
+                return true;
+            }
