    private static final class IntegrityAnalysis {
        private final List<Entry> entries;
        private final List<String> unownedFiles;
        private boolean entriesChanged;

        private IntegrityAnalysis(List<Entry> entries, List<String> unownedFiles) {
            this.entries = entries;
            this.unownedFiles = unownedFiles;
        }

        private boolean hasProblems() {
            return entries.stream().anyMatch(entry -> entry.broken || entry.resolved || entry.shared
                    || entry.misplaced || entry.colliding || entry.occupied) || !unownedFiles.isEmpty();
        }

        private String report(Path index) {
            StringBuilder report = new StringBuilder("Violation store integrity check failed for ")
                    .append(index).append(":");
            addEntries(report, "broken", entry -> entry.broken);
            addEntries(report, "resolved", entry -> entry.resolved);
            addEntries(report, "shared", entry -> entry.shared);
            addEntries(report, "misplaced", entry -> entry.misplaced);
            addEntries(report, "colliding", entry -> entry.colliding);
            addEntries(report, "occupied", entry -> entry.occupied);
            for (String unownedFile : unownedFiles) {
                report.append("\n- unowned file: ").append(unownedFile);
            }
            return report.toString();
        }

        private void addEntries(StringBuilder report, String condition, EntryPredicate predicate) {
            List<Entry> matching = entries.stream().filter(predicate::matches)
                    .sorted(Comparator.comparing(entry -> entry.description)).collect(toList());
            for (Entry entry : matching) {
                report.append("\n- ").append(condition).append(" entry: ")
                        .append(entry.description).append(" -> ").append(entry.fileName);
            }
        }
    }

    @FunctionalInterface
